"""Balanced bracket checking that ignores double-quoted string contents."""

from __future__ import annotations

_OPENING = '([{'
_CLOSING = {')': '(', ']': '[', '}': '{'}


def balanced(s: str) -> bool:
    """Return True when every bracket in *s* is closed in the right order.

    Text inside double-quoted strings is ignored, and a backslash inside a
    string escapes the next character (so ``\"`` does not end the string).
    An unterminated string makes the input unbalanced.
    """
    stack: list[str] = []
    in_string = False
    escaped = False

    for ch in s:
        if in_string:
            if escaped:
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '"':
                in_string = False
        elif ch == '"':
            in_string = True
        elif ch in _OPENING:
            stack.append(ch)
        elif ch in _CLOSING:
            if not stack or stack.pop() != _CLOSING[ch]:
                return False

    return not in_string and not stack

